from lib import *
S = SS('k35')
F1 = [['ResourceQuota q', 'pods 3 / requests.cpu 1 / …'], ['创建 p1', 'requests.cpu 400m'], ['创建 p2', 'requests.cpu 800m'], ['status.used', '实时更新']]
F2 = [['第 3 个 400m 的 Pod', 'requests.cpu 超限 → 拒绝'], ['100m 的小 Pod', '通过,pods 3/3'], ['第 4 个小 Pod', 'pods 超限 → 拒绝'], ['Deployment replicas=5', 'READY 2/5']]
F3 = [['配额里有 requests/limits', 'Pod 必须写明'], ['什么都没写', 'failed quota: must specify …'], ['加 LimitRange', '补默认值 → 通过']]
F4 = [['count/configmaps 4', '第 5 个被拒'], ['scopes: BestEffort', '只数 BestEffort Pod'], ['Burstable Pod', '不受影响'], ['删除 Pod', 'used 立即减少']]
PANELS = [('f', 'flow', 'ResourceQuota 的记账'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("ResourceQuota q:pods 3、requests.cpu 1、limits.cpu 2、requests.memory 1Gi、limits.memory 1Gi、count/configmaps 4。刚创建:used 都是 0(configmaps 已有 1 个 kube-root-ca.crt)。创建 p1(requests cpu 400m / memory 200Mi,limits cpu 500m / memory 300Mi)后:pods=1/3、requests.cpu=400m/1、limits.cpu=500m/2;再创建 p2:pods=2/3、requests.cpu=800m/1、limits.cpu=1/2、limits.memory=600Mi/1Gi。", f=fl(F1, cur=[1, 2], done=[0, 3]), t=tl(S(1), mark=lidx(S(1), '创建 p1', '创建 p2')), kv=KV([['记账', '创建时按 requests/limits 累加到 status.used'], ['每种资源独立', '哪个先到上限就卡哪个'], ['count/…', '还能给任意资源按个数计数']], ['记账'])),
    step("超额在创建 Pod 的那一刻被拒绝:第 3 个同样的 Pod → exceeded quota: q, requested: requests.cpu=400m, used: requests.cpu=800m, limited: requests.cpu=1;换成 100m / 50Mi 的小 Pod(第 3 个)通过,pods=3/3;再来一个小的 → exceeded quota: q, requested: pods=1, used: pods=3, limited: pods=3。用 replicas=5 的 Deployment:Deployment 创建成功,READY 只有 2/5,ReplicaSet 的 FailedCreate 事件是 Error creating: pods … is forbidden: exceeded quota。", f=fl(F2, cur=[0, 2, 3], done=[1]), t=tl(S(2), mark=lidx(S(2), 'exceeded quota', 'FailedCreate', '2/5'), done=lidx(S(2), 'pod/s1 created')), kv=KV([['拒绝点', 'Pod 的创建请求(准入)'], ['Deployment', '本身能创建,Pod 创建不出来,表现为 READY 不足'], ['看原因', 'kubectl describe rs / events']], ['Deployment'])),
    step("配额里有 requests / limits 时,Pod 必须写明:什么都没写的 Pod → failed quota: q: must specify limits.cpu for: c; limits.memory for: c; requests.cpu for: c; requests.memory for: c。同一命名空间加一个 LimitRange(补默认值)之后,同一个 Pod 创建成功,配额随之记账(pods 2/3、requests.cpu 200m/1)。", f=fl(F3, cur=[1], done=[2]), t=tl(S(3), mark=lidx(S(3), 'failed quota'), done=lidx(S(3), 'pod/naked created')), kv=KV([['ResourceQuota + LimitRange', '经典搭配:一个限总量,一个补默认'], ['没有默认值', '没写资源的 Pod 直接被拒'], ['缺哪项', '报错逐项列出']], ['ResourceQuota + LimitRange'])),
    step("对象数量配额:count/configmaps 上限 4,命名空间里已有 kube-root-ca.crt 加成功创建的 3 个,再建一个 → exceeded quota: q, requested: count/configmaps=1, used: count/configmaps=4, limited: count/configmaps=4。另一个命名空间里 scopes: [BestEffort]、pods: 1 的配额:第 1 个 BestEffort Pod 成功,第 2 个被拒;Burstable 的 Pod 不受它管,used 只是 {pods: 1};删除 be1 之后 used 变回 {pods: 0}。", f=fl(F4, cur=[0, 1], done=[2, 3]), t=tl(S(4), mark=lidx(S(4), 'one-more', 'be2'), done=lidx(S(4), 'bu1', '删除 be1')), kv=KV([['scopes', '让配额只统计某一类 Pod(BestEffort、PriorityClass 等)'], ['count/<资源>', '按个数限制任何命名空间级资源'], ['删除对象', 'used 很快跟着减少']], ['scopes'])),
]
A = mkartk('k35', 35, 'Kubernetes,ResourceQuota,资源配额,准入控制,scopes,count 配额,真实验证,动画演示',
    '在 kind 集群里实测 ResourceQuota:创建 Pod 时 status.used 立即累加;requests.cpu、pods 等超限的 Pod 在创建那一刻被拒绝(exceeded quota: …, requested/used/limited),Deployment 能创建但 ReplicaSet 创建 Pod 被拒、READY 只有 2/5;配额里有 requests/limits 时 Pod 必须写明,配合 LimitRange 补默认值才能通过;count/configmaps 限制个数;scopes: [BestEffort] 只统计 BestEffort Pod,删除后用量立即归零。',
    '命名空间的资源总量上限是怎么执行的?超了会在哪一步失败?为什么 Deployment 看起来创建成功了 Pod 却起不来?这篇用一个 ResourceQuota 把记账、拒绝点、与 LimitRange 的搭配、对象数量配额和 scope 范围都量了一遍。',
    [('exceeded quota', '超额请求被拒绝的原因,写明 requested、used、limited 三个数字'), ('READY 2/5', 'replicas=5 的 Deployment 在 pods 配额还剩 2 个时的状态'), ('{pods: 1}', 'scopes: [BestEffort] 的配额在有 1 个 BestEffort 和 1 个 Burstable Pod 时的用量')],
    [('配额怎么记账', '<p>ResourceQuota 对每种资源分别记账。创建 p1(requests cpu 400m / memory 200Mi,limits cpu 500m / memory 300Mi)之后,<code>status.used</code> 里 <code>pods=1/3</code>、<code>requests.cpu=400m/1</code>、<code>limits.cpu=500m/2</code>;再创建 p2,<code>requests.cpu</code> 到 800m、<code>limits.memory</code> 到 600Mi。用量在创建那一刻就更新。<code>count/configmaps</code> 这种写法可以给任何命名空间级资源按个数计数。</p>'),
     ('超了在哪一步失败', '<p>准入阶段、创建对象的那个请求被拒绝:第 3 个 400m 的 Pod 报 <code>exceeded quota: q, requested: requests.cpu=400m, used: requests.cpu=800m, limited: requests.cpu=1</code>,小 Pod 能放进去直到 <code>pods=3/3</code>,再多一个报 <code>requested: pods=1, used: pods=3, limited: pods=3</code>。用 Deployment 时,Deployment 本身创建成功,失败的是它的 ReplicaSet 去创建 Pod 那一步:<code>kubectl get deploy</code> 显示 <code>2/5</code>,原因要看 ReplicaSet 的 <code>FailedCreate</code> 事件。</p>'),
     ('必须写明资源', '<p>配额里管着 requests / limits 的时候,没写这些字段的 Pod 直接被拒:<code>failed quota: q: must specify limits.cpu for: c; limits.memory for: c; requests.cpu for: c; requests.memory for: c</code>。同命名空间加一个 LimitRange 补默认值,同一个 Pod 就能创建,并且按补完的值记账。ResourceQuota 管总量,LimitRange 管单个对象和默认值,常常成对使用。</p>'),
     ('数量与范围', '<p><code>count/configmaps: 4</code> 在命名空间里已有 <code>kube-root-ca.crt</code> 加 3 个之后拒绝第 5 个。<code>scopes: [BestEffort]</code> 让配额只统计 BestEffort 的 Pod:第 1 个 BestEffort Pod 通过,第 2 个被拒,Burstable 的 Pod 不受影响,<code>status.used</code> 只是 <code>{pods: 1}</code>;删掉 Pod 之后 <code>used</code> 立刻回到 0。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0);命名空间 k35 里的 ResourceQuota q:pods 3、requests.cpu 1、limits.cpu 2、requests.memory 1Gi、limits.memory 1Gi、count/configmaps 4,另在 k35b 里建 scopes: [BestEffort]、pods: 1 的配额 be(同一个命名空间里放两个配额会互相影响,第一次这样做时被另一个配额的“必须写明资源”规则干扰了,所以分开);Pod 用 busybox:1.36;用量读自 status.used;每种情形各一次',
     '没有验证:PriorityClass、Terminating / NotTerminating 等其他 scope;scopeSelector 的表达式;存储类配额(requests.storage、<class>.storageclass.storage.k8s.io/…);配额在对象更新(如 resize)时的重新计算;配额控制器的重新同步延迟(用量更新在本实验里是即时的);超额之后已存在的对象不会被驱逐'],
    'ResourceQuota 记账', PANELS)
